SourceCode.Declaration:
/// <summary>
///     This class illustrates how to start query report with some printer settings 
/// </summary>
class LACTutorialStartReport
{
}

Method.Source:
public static void main(Args   _args)
{
    LACRunQueryServiceController    controller = LACRunQueryServiceController::newReport("LACCustTable", LACArgsCache::newCache('LACCustTable'), true); // loading last values, make sure you have report named here
    SRSPrintDestinationSettings     printSettings;
    Query                           query;
    LACParametersMap                map;
    MapEnumerator                   mapEnumerator;
    map                             customPropertyMap;
    // Setting up query ranges you would like to use

    query         = controller.parmQuery();
    query.dataSourceTable(tableNum(CustTable)).addRange(fieldNum(CustTable, AccountNum)).value("004011");  // Do You have this customer account?
    // Setting up destination
    printSettings = controller.parmPrintSettings();
    printSettings.printMediumType(SRSPrintMediumType::LAC); // This is to call Lasernet Print Option
    printSettings.lacDestinationSettings().destTypes4Print(LACDestTypes4Print::Email);
    printSettings.lacDestinationSettings().emailTo("test@contoso.com");

    //Ilustrating usage of Custom properties - allowing to put any value into XML  that can be retrieved in Lasernet, i.e. for Layout choosing
    // Retrieving map with Custom properties
    Map customPropertiesMap = printSettings.lacDestinationSettings().customPropertyMap();
    // Set custom property to pass Additional information. This goes into XML and can be used in Lasernet designer
    customPropertiesMap.add('CustomProperty_CustomParameter', 'ThisIsValueAddedFromCode');
    printSettings.lacDestinationSettings().customPropertyMap(customPropertiesMap);

    //Ilustrating usage of Parameter - allowing to put value into same Parameterg as is configured through Report dialog setup
    // Look for this property in the XML file. You should be able to use it as criteria to choose the correct Layout
    // Retrieving map of packed parameters from the data contract
    container con = controller.parmLACRunQueryDataContract().parmParametersRunPack();
    LACParametersMap parametersMap = LACParametersMap::create(con);

    // Set paramter value by adding element to the map. It must be called the same as Parameter in Report Dialog setup
    parametersMap.insert('CustomParameter', 'ThisIsValueAddedFromCode', 'ThisIsValueAddedFromCode');
    // Passing packed parameters
    controller.parmLACRunQueryDataContract().parmParametersRunPack(parametersMap.pack());


    // Attach documents printing
    printSettings.lacDestinationSettings().manualDocuRefType(LACManualOverwriteType::Disabled); // No attachments
    // Stting up overlay
    printSettings.lacDestinationSettings().allowManualOverlay(true);                  // Overwriting overlay
    printSettings.lacDestinationSettings().manualOverlayType(LACManualOverwriteType::Overwrite);
    printSettings.lacDestinationSettings().overlayId("MyOverlay");
    printSettings.lacDestinationSettings().forceEnabled(NoYes::Yes);
         // controller.this.getParameter('AccountNum'); // lookup always returs Str value

    controller.parmShowDialog(false);    // Showing dialog, can be switched off
    controller.startOperation();        // Will show dialog and run the report
}
